            emon.Port.cellsPush(tbk, hfirst);
            emon.Port.cellsPush(tbk, hcount);
            emon.Port.cellsPush(tbk, occ);
            emon.Port.cellsPush(tbk, evidence);
            emon.Port.cellsPush(tbk, -1);
            col += 1;
